feedbackvariables.text:
[rayList, ptList]: args(ans1)$

incident_candidates: []$
for r in rayList do (
  if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) and length(r[3]) > 0 then (
    if line_thru(r[1], r[2], Bx, By, 0.3) then (
      inter: mirror_intersect(r[1], r[2]),
      if inter # false and on_mirror_segment(inter[1], xtol) then
        incident_candidates: append(incident_candidates, [[r[3], inter[1]]])
    )
  )
)$

reflected_candidates: []$
for r in rayList do (
  if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) and length(r[3]) > 0 then (
    if line_thru(r[1], r[2], Bpx, Bpy, 0.3) then (
      inter: mirror_intersect(r[1], r[2]),
      if inter # false and on_mirror_segment(inter[1], xtol) then
        reflected_candidates: append(reflected_candidates, [[r[3], inter[1]]])
    )
  )
)$

any_attempt: is(length(incident_candidates) > 0 or length(reflected_candidates) > 0)$

all_pairs: []$
for ic in incident_candidates do (
  for rc in reflected_candidates do (
    Ix: ic[2],
    Ix2: rc[2],
    if abs(Ix - Ix2) < xtol then (
      inc_pieces: ic[1],
      refl_pieces: rc[1],
      xNear: min(Bx, Ix), xFar: max(Bx, Ix),
      dirsign1: if Ix >= Bx then 1 else -1,
      xBeyond1: Ix + dirsign1*1.0,
      inc_real_ok: is(eff_status(status_covering_x(inc_pieces, xNear + xtol, xtol)) = 1
                and eff_status(status_covering_x(inc_pieces, xFar - xtol, xtol)) = 1),
      inc_absent_ok: is(status_covering_x(inc_pieces, xBeyond1, xtol) = -1),
      inc_full: is(inc_real_ok and inc_absent_ok),
      dirsign2: if Bpx >= Ix then 1 else -1,
      xReal2: Ix - dirsign2*1.0,
      xVNear: min(Ix, Bpx) + xtol, xVFar: max(Ix, Bpx) - xtol,
      refl_real_ok: is(eff_status(status_covering_x(refl_pieces, xReal2, xtol)) = 1),
      refl_virtual_ok: is(eff_status(status_covering_x(refl_pieces, xVNear, xtol)) = 2
                and eff_status(status_covering_x(refl_pieces, xVFar, xtol)) = 2),
      refl_full: is(refl_real_ok and refl_virtual_ok),
      inc_score: if inc_full then 1 else GEOM_WEIGHT,
      refl_score: if refl_full then 1 else GEOM_WEIGHT,
      pair_score: (inc_score + refl_score)/2,
      all_pairs: append(all_pairs, [[Ix, pair_score]])
    )
  )
)$

accepted: []$
for pr in all_pairs do (
  is_dup: false,
  for a in accepted do (if abs(a[1] - pr[1]) < xtol then is_dup: true),
  if not is_dup and length(accepted) < 2 then accepted: append(accepted, [pr])
)$

nb_accepted: length(accepted)$
nb_bonnes: if nb_accepted = 0 then 0 elseif nb_accepted = 1 then accepted[1][2] else accepted[1][2] + accepted[2][2]$
score_rayons: min(nb_bonnes/2, 1)$

have2: is(nb_accepted >= 2)$

c_point: is(found_point(ptList, Bpx, Bpy, 0.3))$
